        next=curr->next;
        curr->next=prev;
        prev=curr;
        curr=next;
    }
    head=prev;

    cout<<"Reversed Linked List: ";
    temp=head;
    while(temp!=NULL){
        cout<<temp->data<<" ";
        temp=temp->next;
    }

    return 0;
}

