#include<iostream>
using namespace std;

class Stack{
    int arr[100],top;
public:
    Stack(){top=-1;}

    void push(int x){
        if(top==99){
            cout<<"Stack Overflow\n";
            return;
        }
        arr[++top]=x;
    }

    void pop(){
        if(top==-1){
            cout<<"Stack Underflow\n";
            return;
        }
        cout<<"Deleted Element: "<<arr[top--]<<endl;
    }

    void display(){
        if(top==-1){
            cout<<"Stack Empty";
            return;
        }
        cout<<"Stack Elements: ";
        for(int i=top;i>=0;i--)
            cout<<arr[i]<<" ";
        cout<<endl;
    }
};

int main(){
    Stack s;
    s.push(10);
    s.push(20);
    s.push(30);
    s.display();
    s.pop();
    s.display();
    return 0;
}

#include<iostream>
using namespace std;

struct Node{
    int data;
    Node *next;
};

Node *top=NULL;

void push(int x){
    Node *temp=new Node();
    temp->data=x;
    temp->next=top;
    top=temp;
}

void pop(){
    if(top==NULL){
        cout<<"Stack Underflow"<<endl;
        return;
    }
    Node *temp=top;
    cout<<"Deleted Element: "<<top->data<<endl;
    top=top->next;
    delete temp;
}

void display(){
    Node *temp=top;
    cout<<"Stack: ";
    while(temp){
        cout<<temp->data<<" ";
        temp=temp->next;
    }
    cout<<endl;
}

int main(){
    push(10);
    push(20);
    push(30);
    display();
    pop();
    display();
    return 0;
}
